{
  "name": "实验工作台布局管理组件",
  "name_en": "Worktable Layout Manager",
  "manufacturer": "",
  "description": "用于表示和管理自动化移液工作台上载架、孔板、试剂槽、吸头架与孔位位置关系的非实体软件组件。它可解析工作台模板文件，维护 labware 与 DiTi 吸头系列，记录当前对象与下一个可用位置，并为实验协议提供布局、选择和位置计算信息。",
  "description_en": "A non-physical software component for representing and managing the layout of carriers, labware, wells, tip racks, and positions on an automated liquid-handling worktable. It can parse worktable template files, maintain labware and DiTi tip series, track the current object and next usable position, and provide layout, selection, and position-calculation information for experiment protocols.",
  "tag_hints": [
    "liquid-handling deck layout",
    "labware position tracking",
    "tip rack management",
    "well selection",
    "worktable template parsing",
    "protocol setup",
    "carrier and labware mapping"
  ],
  "actions": [
    {
      "action_name": "auto-parse_worktable_file",
      "description": "解析工作台模板文件并导入布局信息。",
      "description_en": "Parse a worktable template file and import layout information."
    },
    {
      "action_name": "auto-add_new_labware",
      "description": "向工作台添加新的实验器皿并分配位置。",
      "description_en": "Add a new labware item to the worktable and assign a position."
    },
    {
      "action_name": "auto-add_labware",
      "description": "将实验器皿添加到指定工作台位置。",
      "description_en": "Add a labware item to a specified worktable location."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置当前实验器皿。",
      "description_en": "Set the current labware."
    },
    {
      "action_name": "auto-set_first_pos",
      "description": "设置指定实验器皿类型的起始孔位或吸头位置。",
      "description_en": "Set the starting well or tip position for a specified labware type."
    },
    {
      "action_name": "auto-retire_labware",
      "description": "停用或移除指定实验器皿。",
      "description_en": "Retire or remove a specified labware item."
    },
    {
      "action_name": "auto-replace_with_new",
      "description": "用新的实验器皿替换现有实验器皿。",
      "description_en": "Replace an existing labware item with a new one."
    },
    {
      "action_name": "auto-set_def_DiTi",
      "description": "设置默认 DiTi 吸头配置。",
      "description_en": "Set the default DiTi tip configuration."
    },
    {
      "action_name": "auto-get_current_labware",
      "description": "获取当前实验器皿。",
      "description_en": "Get the current labware."
    },
    {
      "action_name": "auto-get_labware",
      "description": "获取实验器皿。",
      "description_en": "Get labware."
    },
    {
      "action_name": "auto-get_DITI_series",
      "description": "获取 DiTi 吸头架系列。",
      "description_en": "Get the DiTi tip rack series."
    },
    {
      "action_name": "auto-log",
      "description": "记录对象或布局相关日志信息。",
      "description_en": "Log object- or layout-related information."
    },
    {
      "action_name": "auto-select",
      "description": "选择孔位、吸头或其他布局对象。",
      "description_en": "Select wells, tips, or other layout objects."
    },
    {
      "action_name": "auto-vol",
      "description": "定义体积属性。",
      "description_en": "Define the volume property."
    },
    {
      "action_name": "auto-reagent",
      "description": "定义试剂属性。",
      "description_en": "Define the reagent property."
    },
    {
      "action_name": "auto-actions",
      "description": "列出对象支持的操作。",
      "description_en": "List the actions supported by the object."
    },
    {
      "action_name": "auto-create",
      "description": "创建布局对象实例。",
      "description_en": "Create a layout object instance."
    },
    {
      "action_name": "auto-init_wells",
      "description": "初始化孔位集合。",
      "description_en": "Initialize the set of wells."
    },
    {
      "action_name": "auto-autoselect",
      "description": "自动选择合适的孔位或对象。",
      "description_en": "Automatically select suitable wells or objects."
    },
    {
      "action_name": "auto-offset",
      "description": "定义位置偏移量。",
      "description_en": "Define the position offset."
    },
    {
      "action_name": "auto-offsetFromName",
      "description": "根据名称计算位置偏移量。",
      "description_en": "Calculate a position offset from a name."
    },
    {
      "action_name": "auto-position",
      "description": "获取或生成位置表示。",
      "description_en": "Get or generate a position representation."
    },
    {
      "action_name": "auto-find_free_wells",
      "description": "查找空闲孔位。",
      "description_en": "Find free wells."
    },
    {
      "action_name": "auto-put",
      "description": "将对象放入指定位置。",
      "description_en": "Place an object into a specified position."
    },
    {
      "action_name": "auto-clearSelection",
      "description": "清除当前选择。",
      "description_en": "Clear the current selection."
    },
    {
      "action_name": "auto-selected",
      "description": "获取当前选择状态。",
      "description_en": "Get the current selection state."
    },
    {
      "action_name": "auto-selected_wells",
      "description": "获取已选择孔位。",
      "description_en": "Get the selected wells."
    },
    {
      "action_name": "auto-selectAll",
      "description": "选择全部孔位或对象。",
      "description_en": "Select all wells or objects."
    },
    {
      "action_name": "auto-selectOnly",
      "description": "仅选择指定孔位或对象。",
      "description_en": "Select only the specified wells or objects."
    },
    {
      "action_name": "auto-newOffset",
      "description": "创建新的位置偏移量。",
      "description_en": "Create a new position offset."
    },
    {
      "action_name": "auto-newPosition",
      "description": "创建新的位置对象。",
      "description_en": "Create a new position object."
    },
    {
      "action_name": "auto-posAtParallelMove",
      "description": "计算并行移动时的位置。",
      "description_en": "Calculate the position for a parallel move."
    },
    {
      "action_name": "auto-parallelOrder",
      "description": "计算并行移动顺序。",
      "description_en": "Calculate the order for parallel movement."
    },
    {
      "action_name": "auto-offsetAtParallelMove",
      "description": "计算并行移动时的偏移量。",
      "description_en": "Calculate the offset for a parallel move."
    },
    {
      "action_name": "auto-moveParallel",
      "description": "执行并行位置移动计算。",
      "description_en": "Perform parallel position movement calculation."
    },
    {
      "action_name": "auto-wellSelectionStr",
      "description": "生成孔位选择字符串。",
      "description_en": "Generate a well-selection string."
    },
    {
      "action_name": "auto-find_new_tips",
      "description": "查找新的可用吸头。",
      "description_en": "Find new available tips."
    },
    {
      "action_name": "auto-retire_new_tips",
      "description": "将新吸头标记为已使用或停用。",
      "description_en": "Mark new tips as used or retire them."
    },
    {
      "action_name": "auto-refill_next_rack",
      "description": "切换或补充下一个吸头架。",
      "description_en": "Switch to or refill the next tip rack."
    },
    {
      "action_name": "auto-create_labware",
      "description": "创建实验器皿对象。",
      "description_en": "Create a labware object."
    },
    {
      "action_name": "auto-create_series",
      "description": "创建实验器皿或吸头架系列。",
      "description_en": "Create a labware or tip-rack series."
    },
    {
      "action_name": "auto-set_DITI_counter",
      "description": "设置 DiTi 吸头计数器。",
      "description_en": "Set the DiTi tip counter."
    },
    {
      "action_name": "auto-fill",
      "description": "填充孔位或容器的内容状态。",
      "description_en": "Fill wells or containers in the content model."
    },
    {
      "action_name": "auto-set_back",
      "description": "将对象状态或位置设回先前值。",
      "description_en": "Set an object's state or position back to a previous value."
    },
    {
      "action_name": "auto-pick_up",
      "description": "从布局中取用吸头或对象。",
      "description_en": "Pick up a tip or object from the layout."
    },
    {
      "action_name": "auto-waste",
      "description": "将对象标记为废弃或送入废弃位。",
      "description_en": "Mark an object as waste or send it to a waste position."
    },
    {
      "action_name": "auto-write",
      "description": "写出布局或对象信息。",
      "description_en": "Write out layout or object information."
    },
    {
      "action_name": "auto-grid_carrier_line",
      "description": "生成或解析网格载架行信息。",
      "description_en": "Generate or parse a grid carrier line."
    },
    {
      "action_name": "auto-parse_file",
      "description": "解析定义文件或布局文件。",
      "description_en": "Parse a definition or layout file."
    },
    {
      "action_name": "auto-add_type",
      "description": "添加实验器皿类型定义。",
      "description_en": "Add a labware type definition."
    },
    {
      "action_name": "auto-size",
      "description": "获取尺寸或容量规模信息。",
      "description_en": "Get size or capacity-scale information."
    },
    {
      "action_name": "auto-to_name",
      "description": "转换为名称表示。",
      "description_en": "Convert to a name representation."
    },
    {
      "action_name": "auto-add",
      "description": "添加子对象或成员。",
      "description_en": "Add a child object or member."
    },
    {
      "action_name": "auto-remove",
      "description": "移除子对象或成员。",
      "description_en": "Remove a child object or member."
    },
    {
      "action_name": "auto-set_next",
      "description": "设置下一个可用位置或对象。",
      "description_en": "Set the next available position or object."
    },
    {
      "action_name": "auto-set_current_next_to",
      "description": "设置当前对象旁边的下一个位置。",
      "description_en": "Set the next position adjacent to the current object."
    },
    {
      "action_name": "auto-show_next_to",
      "description": "显示指定对象旁边的下一个位置。",
      "description_en": "Show the next position adjacent to a specified object."
    },
    {
      "action_name": "auto-show_next",
      "description": "显示下一个可用位置或对象。",
      "description_en": "Show the next available position or object."
    }
  ]
}

